//! Bit-exact parity against the Python reference fold.
//!
//! tests/data/parity.txt is generated by tools/gen_rust_vectors.py from
//! src/memochain/fold.py (Folder(seed=0), 5 deterministic docs). This test
//! replays the same documents and asserts every intermediate state matches
//! the Python int16 grid exactly.

use std::fs;
use std::path::Path;

struct Vectors {
    w_key: Vec<i16>,
    w_val: Vec<i16>,
    beta: i64,
    decay: i64,
    n_docs: usize,
    doc_dim: usize,
    docs: Vec<i16>,
    states: Vec<Vec<i16>>,
}

fn parse(path: &Path) -> Vectors {
    let text = fs::read_to_string(path).expect("parity.txt missing; run tools/gen_rust_vectors.py");
    let mut tokens = text.split_whitespace();

    let mut section = String::new();
    let mut count = 0usize;
    let mut values: Vec<i64> = Vec::new();
    let mut sections: Vec<(String, Vec<i64>)> = Vec::new();

    loop {
        let Some(tok) = tokens.next() else { break };
        if count == 0 {
            if !section.is_empty() {
                sections.push((std::mem::take(&mut section), std::mem::take(&mut values)));
            }
            section = tok.to_string();
            count = tokens.next().expect("section count").parse().unwrap();
        } else {
            values.push(tok.parse().expect("integer"));
            count -= 1;
        }
    }
    if !section.is_empty() {
        sections.push((section, values));
    }

    let get = |name: &str| -> &[i64] {
        &sections
            .iter()
            .find(|(n, _)| n == name)
            .unwrap_or_else(|| panic!("missing section {name}"))
            .1
    };

    let w_key = get("W_KEY").iter().map(|&x| x as i16).collect::<Vec<_>>();
    let w_val = get("W_VAL").iter().map(|&x| x as i16).collect::<Vec<_>>();
    let beta = get("BETA")[0];
    let decay = get("DECAY")[0];
    let n_docs = get("N_DOCS")[0] as usize;
    let doc_dim = get("DOC_DIM")[0] as usize;
    let docs = get("DOCS").iter().map(|&x| x as i16).collect::<Vec<_>>();
    let states = (0..n_docs)
        .map(|i| get(&format!("STATE_{i}")).iter().map(|&x| x as i16).collect::<Vec<_>>())
        .collect();

    assert_eq!(w_key.len(), 11 * 32 * 32);
    assert_eq!(docs.len(), n_docs * doc_dim);

    Vectors { w_key, w_val, beta, decay, n_docs, doc_dim, docs, states }
}

fn chunked(v: &[i16], n: usize, dim: usize) -> Vec<Vec<i16>> {
    assert_eq!(v.len(), n * dim);
    (0..n).map(|i| v[i * dim..(i + 1) * dim].to_vec()).collect()
}

#[test]
fn fold_matches_python_bit_for_bit() {
    let v = parse(Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/parity.txt").as_path());

    let heads = 11usize;
    let key_dim = 32usize;
    let val_dim = 32usize;
    let key_part = heads * key_dim;

    let folder = memochain_core::Folder {
        w_key: chunked(v.w_key.as_slice(), heads, key_dim * key_dim),
        w_val: chunked(v.w_val.as_slice(), heads, val_dim * key_dim),
        beta: v.beta,
        decay: v.decay,
    };
    assert_eq!(v.doc_dim, memochain_core::DOC_DIM);

    let docs = chunked(v.docs.as_slice(), v.n_docs, v.doc_dim);
    let mut state = memochain_core::zero_state();
    for (i, doc) in docs.iter().enumerate() {
        state = folder.fold(&state, doc);
        assert_eq!(
            state, v.states[i],
            "state mismatch after doc {i} (bit-exact parity failed)"
        );
    }
}
